class D{String s(boolean p,String I){var L=I.split("\\R");var c=new int[L.length];long A=0;for(int i=0;i<L.length;i++){var b=new int[100];var a=L[i].split("[:|]");for(var x:a[1].trim().split("\\s+"))b[Integer.parseInt(x)]=1;int n=0;for(var x:a[2].trim().split("\\s+"))if(b[Integer.parseInt(x)]>0)n++;if(p)A+=n<1?0:1L<<n-1;else{A+=++c[i];for(int j=0;j<n;)c[i+ ++j]+=c[i];}}return A+"";}}
